 d=pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).sort_values('date'); d=d[d.date<=end]; r=d.close.pct_change();
 v10=r.rolling(10,min_periods=10).std(); v60=r.rolling(60,min_periods=30).std();
