  q=pd.Series(q);print(h,'d',len(q),'IC %.6f ICIR %.6f'%(q.mean(),q.mean()/q.std()))
 v['year']=v.index.year;print(v.groupby('year').ic.mean().round(5).to_dict())
if __name__=='__main__':calc()
"}

